cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db', {readonly: true});

// Get travel_expenses and parse cells properly
const row = db.prepare(\"SELECT * FROM ob_excel_files WHERE file_path = 'data/travel_expenses.xlsx'\").get();
const cells = JSON.parse(row.cells_json);

// Reconstruct values from character arrays
const reconstructed = {};
Object.entries(cells).forEach(([key, charObj]) => {
  if (typeof charObj === 'object') {
    const chars = Object.keys(charObj).sort((a,b) => Number(a) - Number(b)).map(k => charObj[k]);
    reconstructed[key] = chars.join('');
  } else {
    reconstructed[key] = String(charObj);
  }
});

// Parse into rows
const maxRow = Math.max(...Object.keys(reconstructed).map(k => { const m = k.match(/R(\d+)C/); return m ? Number(m[1]) : 0; }));
const maxCol = Math.max(...Object.keys(reconstructed).map(k => { const m = k.match(/C(\d+)/); return m ? Number(m[1]) : 0; }));

for (let r = 1; r <= maxRow; r++) {
  const row = [];
  for (let c = 1; c <= maxCol; c++) {
    const key = 'Travel:R' + r + 'C' + c;
    row.push(reconstructed[key] || '');
  }
  console.log(row.join(' | '));
}
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db', {readonly: true});

// Check budget.xlsx
const row = db.prepare(\"SELECT * FROM ob_excel_files WHERE file_path LIKE '%budget%'\").get();
if (row) {
  const cells = JSON.parse(row.cells_json);
  const reconstructed = {};
  Object.entries(cells).forEach(([key, charObj]) => {
    if (typeof charObj === 'object') {
      const chars = Object.keys(charObj).sort((a,b) => Number(a) - Number(b)).map(k => charObj[k]);
      reconstructed[key] = chars.join('');
    } else {
      reconstructed[key] = String(charObj);
    }
  });

  // Get all sheet prefixes
  const sheets = [...new Set(Object.keys(reconstructed).map(k => k.split(':')[0]))];
  sheets.forEach(sheet => {
    console.log('\\n=== Sheet:', sheet, '===');
    const sheetCells = Object.entries(reconstructed).filter(([k]) => k.startsWith(sheet + ':'));
    const maxRow = Math.max(...sheetCells.map(([k]) => { const m = k.match(/R(\d+)C/); return m ? Number(m[1]) : 0; }));
    const maxCol = Math.max(...sheetCells.map(([k]) => { const m = k.match(/C(\d+)/); return m ? Number(m[1]) : 0; }));
    for (let r = 1; r <= maxRow; r++) {
      const row = [];
      for (let c = 1; c <= maxCol; c++) {
        row.push(reconstructed[sheet + ':R' + r + 'C' + c] || '');
      }
      console.log(row.join(' | '));
    }
  });
}
"

